stageCss:
#stage .rx-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .rx-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
}
#stage .rx-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0; font-size:24px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.42);
}
#stage .rx-app{
  color:var(--text-primary); font-size:22px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .rx-rt{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:8px; }
#stage .rx-rt b{
  color:#fff; font-family:var(--font-mono); font-size:29px; font-weight:700;
  font-variant-numeric:tabular-nums; transition:color .3s ease;
}
#stage .rx-rt.ok b{ color:var(--success); }
#stage .rx-rt.bad b{ color:var(--danger); }
#stage .rx-rt i{ color:var(--text-dim); font-size:19px; font-weight:600; font-style:normal; }

/* ============================= SCENE STACK ============================= */
#stage .rx-body{ position:relative; flex:1; min-height:0; }
#stage .rx-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .rx-sc.on{ opacity:1; transform:none; }
#stage .rx-sc.whip{ animation:rx-whip .44s cubic-bezier(.19,1,.22,1); }
@keyframes rx-whip{
  0%{ transform:translateX(46px) scale(.984); opacity:0; }
  100%{ transform:none; opacity:1; }
}
#stage .rx-col{ display:flex; flex-direction:column; gap:14px; height:100%; }

/* -------------------------------------------------------------- hero bar -- */
#stage .rx-hero{
  height:122px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .rx-hero.tight{ height:112px; }
#stage .rx-hero.ok{ border-color:rgba(63,185,80,.55); box-shadow:0 0 0 1px rgba(63,185,80,.2), 0 0 46px rgba(63,185,80,.13); }
#stage .rx-hero.bad{ border-color:rgba(244,74,106,.6); box-shadow:0 0 0 1px rgba(244,74,106,.2), 0 0 46px rgba(244,74,106,.15); }
#stage .rx-hero-ic{
  width:58px; height:58px; border-radius:16px; flex-shrink:0; font-size:29px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg,#26344e,#1a2338); border:1.5px solid var(--border);
}
#stage .rx-hero-t{ display:flex; flex-direction:column; gap:7px; min-width:0; }
#stage .rx-hero-t b{ color:#fff; font-size:28px; font-weight:800; letter-spacing:-.4px; white-space:nowrap; }
#stage .rx-hero-t i{ color:var(--text-dim); font-size:20px; font-weight:600; font-style:normal; white-space:nowrap; }
#stage .rx-hero-b{
  margin-left:auto; flex-shrink:0; padding:9px 18px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(244,74,106,.5); background:rgba(244,74,106,.12); color:var(--danger);
  font-family:var(--font-mono); font-size:18px; font-weight:700; letter-spacing:1.2px;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .rx-hero-b.ok{ border-color:rgba(63,185,80,.55); background:rgba(63,185,80,.12); color:var(--success); }

/* ------------------------------------------------------- the tap flood -- */
#stage .rx-grid{
  flex:1; min-height:0; border-radius:24px; padding:20px;
  display:flex; flex-direction:column; gap:16px; align-items:center; justify-content:center;
  background:rgba(20,27,43,.55); border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .rx-grid.hot{ border-color:rgba(244,74,106,.5); box-shadow:0 0 0 1px rgba(244,74,106,.16), inset 0 0 60px rgba(244,74,106,.07); }
#stage .rx-cells{ display:grid; grid-template-columns:repeat(10, 1fr); gap:10px; width:100%; }
#stage .rx-cells i{
  height:52px; border-radius:11px; font-size:26px; font-style:normal; line-height:1;
  display:flex; align-items:center; justify-content:center;
  background:rgba(139,149,167,.1); border:1.5px solid rgba(139,149,167,.18);
  transition:background .2s ease, border-color .2s ease, box-shadow .2s ease;
}
#stage .rx-cells i.lit{
  background:rgba(244,74,106,.2); border-color:rgba(244,74,106,.6);
  box-shadow:0 0 16px rgba(244,74,106,.3);
  animation:rx-pop .34s cubic-bezier(.22,1,.36,1);
}
@keyframes rx-pop{ 0%{ transform:scale(.6); } 60%{ transform:scale(1.12); } 100%{ transform:scale(1); } }
#stage .rx-grid-t{ color:var(--text-dim); font-size:21px; font-weight:600; white-space:nowrap; }

/* -------------------------------------------------------- live counters -- */
#stage .rx-tally{ flex-shrink:0; height:112px; display:flex; gap:12px; }
#stage .rx-tal{
