#stage .rx-tal.hot{ border-color:rgba(244,74,106,.5); box-shadow:0 0 30px rgba(244,74,106,.12); }
#stage .rx-tal span{ font-size:30px; line-height:1; }
#stage .rx-tal b{
  color:#fff; font-family:var(--font-mono); font-size:26px; font-weight:800;
  font-variant-numeric:tabular-nums;
}
