#stage .rx-vs{ flex:1; min-height:0; display:flex; gap:16px; }
#stage .rx-card{
  flex:1; min-width:0; border-radius:26px; padding:26px 20px;
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  text-align:center;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2)); border:1.5px solid var(--border);
