#stage .rx-step.live{
  opacity:1; border-color:rgba(58,160,255,.65); transform:scale(1.015);
  box-shadow:0 0 0 1px rgba(58,160,255,.2), 0 0 46px rgba(58,160,255,.16);
}
#stage .rx-step-no{
  width:44px; height:44px; border-radius:12px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  font-family:var(--font-mono); font-size:21px; font-weight:800; color:var(--text-dim);
  background:rgba(139,149,167,.12); border:1.5px solid rgba(139,149,167,.22);
  transition:color .3s ease, background .3s ease, border-color .3s ease;
