#stage .rx-step-t b{ color:#fff; font-size:26px; font-weight:800; letter-spacing:-.4px; white-space:nowrap; }
#stage .rx-step-t i{ color:var(--text-dim); font-size:20px; font-weight:600; font-style:normal; white-space:nowrap; }
#stage .rx-step-b{
  margin-left:auto; flex-shrink:0; padding:8px 16px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(139,149,167,.22); background:rgba(139,149,167,.1); color:var(--text-dim);
  font-family:var(--font-mono); font-size:19px; font-weight:800; font-variant-numeric:tabular-nums;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .rx-step.live .rx-step-b{ border-color:rgba(58,160,255,.5); background:rgba(58,160,255,.12); color:var(--accent-1); }
#stage .rx-step.done .rx-step-b{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.12); color:var(--success); }

/* ------------------------------------------------------------ old vs new -- */
#stage .rx-split{ display:flex; gap:16px; height:100%; }
#stage .rx-scol{
  flex:1; min-width:0; border-radius:28px; padding:28px 22px;
  display:flex; flex-direction:column; align-items:center; gap:18px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2)); border:1.5px solid var(--border);
}
#stage .rx-scol.bad{ border-color:rgba(244,74,106,.5); box-shadow:inset 0 0 60px rgba(244,74,106,.07); }
#stage .rx-scol.good{ border-color:rgba(63,185,80,.5); box-shadow:inset 0 0 60px rgba(63,185,80,.07); }
#stage .rx-scol-h{ font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:1.3px; white-space:nowrap; }
#stage .rx-scol.bad .rx-scol-h{ color:var(--danger); }
#stage .rx-scol.good .rx-scol-h{ color:var(--success); }
#stage .rx-scol-ic{ font-size:58px; line-height:1; }
#stage .rx-scol-list{ flex:1; width:100%; display:flex; flex-direction:column; justify-content:space-evenly; gap:16px; }
#stage .rx-row{ color:var(--text-primary); font-size:24px; font-weight:600; text-align:center; line-height:1.3; }
#stage .rx-row b{ color:#fff; font-weight:800; }
#stage .rx-scol-x{
  color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:700;
  text-align:center; line-height:1.35;
}
#stage .rx-scol-x.ok{ color:var(--success); }

/* -------------------------------------------------------------- the payoff -- */
#stage .rx-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:22px;
  text-align:center;
}
#stage .rx-badge{
  width:120px; height:120px; border-radius:34px; font-size:58px;
  display:flex; align-items:center; justify-content:center;
