  border:1.5px solid rgba(58,160,255,.5); box-shadow:0 0 60px rgba(58,160,255,.2);
}
#stage .rx-badge-l{ color:var(--accent-1); font-family:var(--font-mono); font-size:21px; font-weight:800; letter-spacing:4px; }
#stage .rx-fin-h{ color:#fff; font-size:66px; font-weight:900; line-height:1.12; letter-spacing:-2px; }
#stage .rx-fin-h em{ font-style:normal; color:var(--accent-1); }
#stage .rx-fin-row{ display:flex; flex-wrap:wrap; gap:12px; justify-content:center; }
#stage .rx-fin-p{
  padding:13px 22px; border-radius:100px; white-space:nowrap;
  background:rgba(58,160,255,.1); border:1.5px solid rgba(58,160,255,.42);
  color:var(--text-primary); font-size:22px; font-weight:700;
}
#stage .rx-save{
  margin-top:6px; padding:15px 26px; border-radius:18px; max-width:840px;
