/* --------------------------------------------------------- bottom strip -- */
#stage .rx-strip{
  height:100px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.72); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
