var RX = window.__RX || (window.__RX = {});

RX.EMOJI = ['🔥', '😂', '👏', '🏏', '🔥', '😂', '🔥', '😮'];

RX.fmt = function(n){
  n = Math.round(n);
  var s = String(n), out = '', c = 0;
  for(var i = s.length - 1; i >= 0; i--){
    out = s.charAt(i) + out; c++;
    if(c % 3 === 0 && i > 0) out = ',' + out;
  }
  return out;
};

/** Ramps a formatted integer into an element over ms. */
RX.ramp = function(sel, from, to, ms){
  var el = MSD.q(sel); if(!el) return;
  var steps = Math.max(1, Math.round(ms / 50)), i = 0;
  var id = MSD.every(50, function(){
    i++;
    var p = Math.min(1, i / steps);
    el.textContent = RX.fmt(from + (to - from) * p);
    if(p >= 1) clearInterval(id);
  });
};

RX.scene = function(id, whip){
  MSD.cls('.rx-sc', 'on', false);
  MSD.cls('#rx-sc-' + id, 'on', true);
  MSD.cls('#rx-sc-' + id, 'whip', false);
  if(whip) MSD.after(20, function(){ MSD.cls('#rx-sc-' + id, 'whip', true); MSD.sfx.swipe(); });
};

RX.header = function(app, rate, unit, tone){
  MSD.q('#rx-app').textContent = app;
  if(rate !== null) MSD.q('#rx-rt-n').textContent = rate;
  MSD.q('#rx-rt-u').textContent = unit;
  MSD.cls('#rx-rt', 'bad', tone === 'bad');
  MSD.cls('#rx-rt', 'ok', tone === 'ok');
};

RX.strip = function(id, label, text, tone){
  MSD.cls(id, 'bad', tone === 'bad');
  MSD.cls(id, 'warn', tone === 'warn');
  MSD.cls(id, 'good', tone === 'good');
  MSD.q(id + '-l').textContent = label;
  MSD.q(id + '-t').textContent = text;
};

/**
 * Drops n reactions onto random phones. Real emoji, not lit rectangles:
 * the flood has to be something the viewer sees, not something the
 * caption claims.
 */
RX.rain = function(n, gap){
  var cells = MSD.qa('#rx-cells i');
  for(var i = 0; i < n; i++){
    (function(i){
      MSD.after(i * (gap || 40), function(){
        var c = cells[Math.floor(Math.random() * cells.length)];
        if(!c) return;
        c.textContent = RX.EMOJI[Math.floor(Math.random() * RX.EMOJI.length)];
        c.classList.remove('lit');
        void c.offsetWidth;
        c.classList.add('lit');
      });
    })(i);
  }
};

RX.clearCrowd = function(){
  MSD.qa('#rx-cells i').forEach(function(el){
    el.classList.remove('lit'); el.textContent = '';
  });
};

RX.way = function(id, value, label, tone){
  MSD.cls(id, 'bad', tone === 'bad');
  MSD.q(id + '-n').textContent = value;
  MSD.q(id + '-x').textContent = label;
};

/**
 * Paints the five-row Azure diagram. "live" is the row being explained
 * right now; everything before it is done, everything after is dimmed.
 */
RX.flow = function(live, badges){
  for(var i = 1; i <= 5; i++){
    MSD.cls('#rx-step-' + i, 'live', i === live);
    MSD.cls('#rx-step-' + i, 'done', live === 0 || i < live);
    MSD.q('#rx-step-' + i + '-b').textContent = badges[i - 1] || '—';
  }
};

RX.scene('crowd');
RX.header('India vs New Zealand · live', '0', 'taps / sec', '');
RX.clearCrowd();
MSD.cls('#rx-grid', 'hot', false);
MSD.cls('.rx-tal', 'hot', false);
MSD.qa('.rx-tal b').forEach(function(el){ el.textContent = '0'; });
RX.strip('#rx-strip', 'THE MOMENT', 'One ball. 25 million phones. Everybody taps at once.', '');

MSD.after(300, function(){ MSD.punch('#rx-hero', 1); MSD.sfx.lock(); });
MSD.after(900, function(){ RX.rain(40, 55); MSD.sfx.data(0); });
MSD.after(1000, function(){
  RX.ramp('#rx-rt-n', 0, 1000000, 2600);
  RX.ramp('#rx-tal-1-n', 0, 412309, 2600);
  RX.ramp('#rx-tal-2-n', 0, 268144, 2600);
  RX.ramp('#rx-tal-3-n', 0, 191880, 2600);
  RX.ramp('#rx-tal-4-n', 0, 127667, 2600);
});
MSD.after(3700, function(){
